from pathlib import Path
import json,html
root=Path('F:/Project Code/BOQ_BBS');out=root/'output/code99-review-verification'
read=lambda n:json.loads((out/n).read_text(encoding='utf-8-sig'));esc=html.escape
r=read('files-audit.json');u=read('unit-results.json');c=read('context.json');assert r['status']=='PASS'and u['success']
assert c['restoredReviewCount']==2 and c['restoredArtifactSha']==c['artifact']['sha256']
checks=[]
for phase in ['setup','review','invalidation','exports','bindings','restore','gui','recovery']:
 p=read(phase+'-results.json');assert not p['cloud']and not p['errors'];assert all(t['status']=='PASS'for t in p['results']);checks+=p['results']
rows=''.join(f'<tr><td>{esc(t["name"])}</td><td>ผ่าน</td></tr>'for t in checks)
pages=''.join(f'<details><summary>{esc(f["sheet"])} · {len(f["pages"])} หน้า</summary>'+''.join(f'<a href="{p["png"]}"><img loading="lazy" src="{p["png"]}" alt="หน้าพิมพ์ {p["page"]}"></a>'for p in f['pages'])+'</details>'for f in r['pdfs'])
text=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>การตรวจรับ Code99 ในแอป BOQ BBS</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#edf2ef;color:#203940;font:16px/1.65 Tahoma,Arial,sans-serif}}main{{max-width:1120px;margin:auto;padding:36px 20px}}h1{{font-size:32px;line-height:1.3}}h2{{font-size:22px}}section{{background:white;border:1px solid #d7e3dc;border-radius:12px;padding:24px;margin:20px 0}}.notice{{background:#fff2dc;border-left:5px solid #b77927;padding:14px}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.stats div{{background:#eaf4ee;padding:16px;border-radius:8px}}.stats strong{{font-size:26px;display:block}}.button{{display:inline-block;background:#1d765f;color:white;padding:9px 14px;border-radius:6px;text-decoration:none;margin:5px 8px 5px 0}}table{{width:100%;border-collapse:collapse}}td,th{{text-align:left;padding:10px;border-bottom:1px solid #dce7e0;overflow-wrap:anywhere}}th{{background:#eaf4ee}}img{{max-width:100%;height:auto;border:1px solid #dce7e0}}details{{margin:18px 0}}summary{{cursor:pointer;font-weight:bold;overflow-wrap:anywhere}}a{{color:#1d765f}}small{{color:#637970}}@media(max-width:650px){{main{{padding:20px 12px}}section{{padding:16px}}h1{{font-size:26px}}.stats{{grid-template-columns:1fr 1fr}}table{{font-size:13px}}}}
</style><main><small>BOQ BBS · รุ่น 0.70 · 14 ตุลาคม 2026 · ทดสอบในเครื่อง</small><h1>การตรวจรับรูปพิเศษ Code99</h1><p>ผู้อนุมัติในทีมโครงการบันทึกผลตรวจรูปพิเศษโดยผูกกับข้อมูลเหล็ก สเป็ค และไฟล์ฉบับปัจจุบัน ช่วยให้ผ่านการตรวจ Code99 ก่อน Checked เมื่อข้อกำหนดอื่นครบ การถอนรับรองและแก้ข้อมูลทำให้ผลตรวจเก่าไม่ใช้กับข้อมูลทำงานใหม่</p><p class="notice">ผ่านเฉพาะการทดสอบซอฟต์แวร์ด้วยข้อมูลสังเคราะห์ ยังไม่ผ่านการตรวจรับระบบเต็มหรือพร้อมออก BBS ก่อสร้าง ไม่แก้หรือ deploy Rules ตามคำสั่งผู้ใช้</p>
<div class="stats"><div><strong>{u['numPassedTests']:,}</strong>กรณีทดสอบย่อย / {len(u['testResults'])} ไฟล์</div><div><strong>{len(checks)}</strong>สถานการณ์จริงในระบบจำลอง</div><div><strong>{r['nativePages']}</strong>หน้า A3 จาก Excel จริง</div><div><strong>2</strong>ผลตรวจใน Frozen และ Backup</div></div>
<section><h2>ผู้อนุมัติตรวจรูปและหลักฐานในสมาชิก</h2><p>รองรับรูปสองเส้นที่ระบบแสดงครบ และแบบเต็มภายนอกสำหรับรูปที่ยังสร้างผิวนอกไม่ได้ เช่น รูปหลายระนาบ กรอกมิติภายนอกเป็นช่องตัวเลขแยกตามช่วง พร้อมป้ายมิติและมิติอิสระ กรอบขนส่งแยกความกว้างและความสูง</p><p>ระบบคงข้อผิดพลาดขั้นต่ำเดิม เพิ่มการตรวจมิติครบและบวกทีละ5mm มิติปลาย ช่วงตรงปลายตามชนิด bar/link มิติอิสระ กรอบขนส่งและเงื่อนไขจัดส่ง การรับรองรูปไม่เป็นการเทียบวัสดุหรือรับรอง BS/ACI อัตโนมัติ</p><img src="external-review-recorded.png" alt="หน้าจอตรวจรับรูปภายนอกด้วยช่องมิติ"><p><a href="../../docs/CODE99_REVIEW.md">คู่มือขั้นตอนตรวจรับ</a></p></section>
<section><h2>แก้ข้อมูลและถอนรับรองโดยคงประวัติ</h2><p>เปลี่ยนข้อมูลสมาชิกแล้วคืนค่าเดิมไม่ทำให้ผลตรวจเดิมกลับมาใช้ได้ การยืนยันมิติหรือตำแหน่งเพียงอย่างเดียวไม่เปลี่ยนรหัสข้อมูล การถอนรับรองเพิ่มประวัติ คืน Draft และไม่ย้อนใช้ผลรับรองที่เก่ากว่า การเปลี่ยนเอกสาร/Spec หรือไม่มีบทบาทผู้อนุมัติทำให้ผลตรวจไม่ผ่านการตรวจชุดปัจจุบัน</p><p>ตรวจ UID และบทบาทที่ระบุในทีมโครงการก่อนใช้ผลรับรอง ผู้ดูแลที่ไม่มีบทบาทผู้อนุมัติลงรับรองแทนไม่ได้ ตรวจไฟล์อ้างอิงจริงก่อน Checked และก่อนตรึงผลรับรองใน Frozen</p><p>แก้คำสั่งตรึง Revision ให้ผู้ตรวจ/ผู้อนุมัติใช้ได้ตาม Rules เดิม โดยอัปเดตเฉพาะ revisionCounter ที่ใช้ตรวจการเปลี่ยนประวัติพร้อมกันอยู่แล้ว การทดสอบเดิมพบการอัปเดตหลายช่องถูกปฏิเสธ และทดสอบซ้ำผ่านหลังแก้แอป การตรวจไฟล์และการอ่านผลรับรองทำก่อนเริ่ม transaction แล้วตรวจรุ่นโครงการและสมาชิกก่อนบันทึก เพื่อหลีกเลี่ยงการรอไฟล์ขณะล็อกข้อมูล</p><img src="delivery-current-review.png" alt="หน้าส่งงานแสดงผลรับรองปัจจุบันและเงื่อนไข Issued ที่ยังไม่ครบ"></section>
<section><h2>Excel เก็บผลตรวจตามฉบับที่ตรึง</h2><p>แผ่น Code99 Review เก็บผู้ตรวจ เวลา มิติ แผนตรวจและข้อมูลอ้างอิง แยกหน้า A3 ต่อผลรับรอง Code99 Details ระบุเมื่อใช้รายละเอียดภายนอก โดยไม่สร้างรูปผิวนอกหรือมิติขึ้นแทนผู้ตรวจ ตรวจความสอดคล้องกับข้อมูล Snapshot ก่อนสร้างไฟล์ และคง cut/count/weight ตาม Frozen</p><p>ตัวอย่างสังเคราะห์รูปแบนใช้มิติ400/600/400 และยาวตัด1375mm รูปหลายระนาบใช้มิติภายนอกที่ผู้ตรวจกรอก400/300/300 ทั้งสองรายการเป็นข้อมูลทดสอบซอฟต์แวร์ ไม่ใช่ผลรับรองของแบบ GULF ข้อแตกต่าง C1 Mark4 และวัสดุ SD40 จากงานก่อนหน้ายังคงต้องตรวจแก้</p><a class="button" href="Code99-user-review-QA.xlsx">Excel ตัวอย่างจากแอปจริง</a><a class="button" href="Code99-review-QA-backup.zip">Backup ชุดทดสอบ</a><p>ตรวจแผ่นงานแบบอ่านอย่างเดียว3มุมมอง และ Excel16.0 จริง4แผ่น/{r['nativePages']}หน้า A3 คง hash ต้นฉบับเดิม Backup/Restore คงผลรับรอง2รายการเป็นประวัติและคืนไฟล์ Excel ด้วย SHA เดิม โครงการใหม่ไม่มีผลรับรองที่ใช้งานอยู่</p><img src="native-contact-sheet.png" alt="หน้าพิมพ์ทั้งหมดจาก Excel จริง">{pages}</section>
<section><h2>หลักฐานและขอบเขตทดสอบ</h2><table><tr><th>สถานการณ์ที่ทดสอบจริง</th><th>ผล</th></tr>{rows}</table><p>ไฟล์ที่คงเดิม9ไฟล์ รวม Rules/Auth/config/.env/BS และแบบ GULF ต้นฉบับ7ไฟล์มี SHA เดิม ไม่มี Cloud Functions การ deploy หรือการเขียนข้อมูล Production ทดสอบสิทธิ์กับ Rules ที่มีอยู่ในเครื่อง ไม่ได้ตรวจหรือเปลี่ยน Rules ของ Production</p><p>ระหว่างเตรียมระบบจำลอง พื้นที่ไดรฟ์เต็มจน Auth/Storage หยุดทำงาน ย้ายเฉพาะ log เก่าที่ไม่มีผู้เขียนไปพื้นที่ของแชต คง log ครบและไม่หยุด Firestore ที่ยังทำงาน กู้ Auth/Storage และไฟล์12รายการจาก Backup ที่ตรวจ SHA แล้วผ่านปลายทาง localhost เท่านั้น การกู้ bytes ด้วยสิทธิ์ผู้ดูแล emulator แยกจากการทดสอบสิทธิ์ของแอป และไม่ได้ใช้เพื่อทำให้กรณีสิทธิ์ผ่าน ต่อมาพบข้อผิดพลาดตัวอ่าน stdout ของ runtime ที่ติดตั้ง เมื่อข้อความ JSON หลายรายการอยู่ใน chunk เดียว คำขอตรวจสิทธิ์จึงค้าง เก็บ Auth/Storage ปัจจุบันครบ52วัตถุและตรวจ5SHAสำคัญก่อนกู้เฉพาะชุด Auth/Storage ของงานนี้ โดยปรับการแบ่งข้อความใน process ของตัวจำลองเท่านั้น ไม่แก้ไฟล์ dependency หรือ Rules Firestoreเดิมยังอยู่ ทดสอบอ่านไฟล์มีสิทธิ์พร้อมกัน16ชุดและปฏิเสธการอ่านเมื่อออกจากระบบผ่าน</p><p><a href="files-audit.json">ผลตรวจไฟล์และหน้าพิมพ์</a> · <a href="protected-config.json">SHA ไฟล์ที่คงเดิม</a> · <a href="service-recovery-admin.json">ผลกู้ไฟล์ระบบจำลอง</a> · <a href="gui-results.json">ผลตรวจหน้าจอรุ่นล่าสุด</a></p></section>
<section><h2>งานก่อนใช้ในโครงการจริง</h2><p class="notice">Issued ยังคงปิด ต้องตรวจ BS/ACI วัสดุ รูปปิดปลาย โมเดลและตำแหน่ง GULF กรณีอ้างอิงที่ผู้รับผิดชอบรับรอง และการยอมรับของเจ้าของงาน รวมถึงงาน stock/offcut และการตรวจรับระบบเต็มตาม12ข้อเดิม</p><p>การตรวจในแอปและการตรวจ UID ของ Rules เดิมไม่แทนการบังคับกฎวิศวกรรมผ่าน API/นโยบายฝั่งเซิร์ฟเวอร์ของ Production ประวัติในไฟล์ Frozen เป็นหลักฐาน ณ เวลาตรึง ไม่ให้สิทธิ์รับรองเมื่อ Restore ไปอีกโครงการ ผู้ใช้เป็นผู้กำหนดและ deploy Rules เอง</p><p><a href="../../docs/CURRENT_REQUIREMENTS_STATUS.md">สถานะข้อกำหนดทั้งหมด</a> · <a href="../code99-excel-verification/DEVELOPMENT_REPORT.html">รายงานรุ่นก่อน</a></p></section></main></html>'''
(out/'DEVELOPMENT_REPORT.html').write_text(text,encoding='utf-8');print('Created scoped review report with engineering and production limits')
